contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doPause) public payable {
        require(true);

        bool pBefore = c.paused();

        bool reverted;
        if (doPause) {
            try c.pause() { reverted = false; } catch { reverted = true; }
        } else {
            try c.unPause() { reverted = false; } catch { reverted = true; }
        }

        bool pAfter = c.paused();

        bool expected = reverted ? pBefore : doPause;
        assert(pAfter == expected || pAfter == pBefore);
    }

    receive() external payable {}
}

